#include "../Source/DelayEngine.h"
#include <iostream>
#include <stdexcept>
void check(bool ok,const char* m){if(!ok)throw std::runtime_error(m);}
int main(){try{for(double sr:{44100.,48000.,96000.})for(int input=0;input<4;++input)for(float width:{1.f,1.35f,2.f}){fm::DelayEngine e;e.prepare(sr);fm::Settings s;s.mode=0;s.timeMs=100;s.feedback=.55f;s.mix=1;s.analog=s.duck=s.diffusion=0;s.hp=20;s.lp=20000;s.ping=true;s.width=width;std::vector<float> l(int(sr*.6)),r(l.size());l[0]=input==2?0:.2f;r[0]=input==1?0:input==3?-.2f:.2f;e.process(l.data(),r.data(),int(l.size()),s);auto peak=[&](const auto& a,int n){float v=0;int t=int(sr*.1*n);for(int i=t-3;i<t+8;++i)v=std::max(v,std::abs(a[i]));return v;};for(int n=1;n<=5;++n){float wanted=peak(n%2?l:r,n),other=peak(n%2?r:l,n);check(wanted>.005f,"every input must produce alternating repeats");check(other<wanted*.001f,"opposite channel must not contain a ghost repeat");if(n>1)check(std::abs(wanted/peak(n%2?r:l,n-1)-.55f)<.005f,"repeat gain follows feedback");}}
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=0;s.timeMs=100;s.mix=1;s.feedback=.5f;s.analog=s.duck=s.diffusion=0;s.hp=20;s.lp=20000;s.ping=true;s.width=0;std::vector<float> l(20000),r(l.size());l[0]=r[0]=.2f;e.process(l.data(),r.data(),int(l.size()),s);check(l==r,"Width zero must deliberately collapse ping-pong to mono");}
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=0;s.timeMs=100;s.mix=1;s.feedback=.5f;s.analog=s.duck=s.diffusion=0;s.hp=20;s.lp=20000;s.ping=false;std::vector<float> l(24000),r(l.size());l[0]=r[0]=.2f;e.process(l.data(),r.data(),7200,s);s.ping=true;std::fill(l.begin(),l.end(),0);std::fill(r.begin(),r.end(),0);e.process(l.data(),r.data(),int(l.size()),s);auto peak=[&](const auto& a,int index){float v=0;for(int i=index-2;i<index+5;++i)v=std::max(v,std::abs(a[i]));return v;};for(int n=0;n<3;++n){int t=2400+n*4800;float wanted=peak(n%2?r:l,t),other=peak(n%2?l:r,t);check(wanted>.005f&&other<wanted*.001f,"enabling Ping must turn an existing centered tail into alternating repeats");}}
 std::cout<<"PASS: five alternating repeats for centered/left/right/anti-phase input at 3 rates and 3 widths; feedback ratios; mono width\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
